begin;
create table if not exists public.mme_financial_control_definitions(control_id uuid primary key default gen_random_uuid(),control_code text not null unique,title text not null,control_domain text not null check(control_domain in('access','approval','transaction','close','vendor','treasury','reporting')),description text not null,frequency text not null check(frequency in('per_transaction','daily','weekly','monthly','quarterly','annual','continuous')),severity text not null default 'medium' check(severity in('low','medium','high','critical')),owner_role text not null,active boolean not null default true,configuration jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.mme_financial_control_executions(execution_id uuid primary key default gen_random_uuid(),control_id uuid not null references public.mme_financial_control_definitions(control_id),period_start date not null,period_end date not null,execution_status text not null check(execution_status in('passed','failed','not_applicable','pending_review')),evidence_reference text,evidence_summary text,executed_by_auth_user_id uuid not null,reviewed_by_auth_user_id uuid,reviewed_at timestamptz,created_at timestamptz not null default now(),check(period_end>=period_start),check(reviewed_by_auth_user_id is null or reviewed_by_auth_user_id<>executed_by_auth_user_id));
create table if not exists public.mme_financial_exceptions(exception_id uuid primary key default gen_random_uuid(),exception_code text not null,domain text not null,source_table text,source_record_id text,severity text not null check(severity in('low','medium','high','critical')),description text not null,exception_status text not null default 'open' check(exception_status in('open','investigating','resolved','accepted_risk','false_positive')),assigned_to_auth_user_id uuid,detected_at timestamptz not null default now(),resolved_by_auth_user_id uuid,resolved_at timestamptz,resolution_note text,created_by_auth_user_id uuid not null,check(resolved_by_auth_user_id is null or resolved_by_auth_user_id<>created_by_auth_user_id));
create table if not exists public.mme_financial_exception_events(event_id uuid primary key default gen_random_uuid(),exception_id uuid not null references public.mme_financial_exceptions(exception_id),event_type text not null check(event_type in('created','assigned','status_changed','commented','resolved','risk_accepted')),from_status text,to_status text,note text,actor_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_financial_approval_authority(authority_id uuid primary key default gen_random_uuid(),role_code text not null,transaction_domain text not null,entity_id uuid references public.mme_financial_reporting_entities(entity_id),currency char(3) not null default 'USD',single_transaction_limit numeric(16,2) not null default 0 check(single_transaction_limit>=0),daily_limit numeric(16,2) not null default 0 check(daily_limit>=0),requires_second_approver boolean not null default true,active boolean not null default true,created_at timestamptz not null default now(),unique(role_code,transaction_domain,entity_id,currency));
create table if not exists public.mme_financial_audit_evidence(evidence_id uuid primary key default gen_random_uuid(),evidence_type text not null,domain text not null,source_table text,source_record_id text,storage_reference text,content_hash text,retention_until date,classification text not null default 'confidential' check(classification in('internal','confidential','restricted')),collected_by_auth_user_id uuid not null,collected_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb);
create table if not exists public.mme_financial_access_reviews(access_review_id uuid primary key default gen_random_uuid(),review_period_start date not null,review_period_end date not null,subject_auth_user_id uuid not null,subject_role text not null,review_status text not null default 'pending' check(review_status in('pending','approved','revoked','exception')),reviewed_by_auth_user_id uuid,reviewed_at timestamptz,review_note text,created_at timestamptz not null default now(),check(review_period_end>=review_period_start),check(reviewed_by_auth_user_id is null or reviewed_by_auth_user_id<>subject_auth_user_id));

insert into public.mme_financial_control_definitions(control_code,title,control_domain,description,frequency,severity,owner_role,configuration) values
('FIN-ACCESS-001','Privileged access review','access','Review privileged finance role assignments and confirm continued business need.','quarterly','high','cfo','{"requires_independent_reviewer":true}'),
('FIN-APPROVAL-001','Independent payment approval','approval','Verify payment creator and approver are different authorized users.','per_transaction','critical','controller','{"self_approval_allowed":false}'),
('FIN-AP-001','Invoice to PO and receipt match','transaction','Document invoice, purchase order and receiving evidence before approval.','per_transaction','high','accounting_manager','{"variance_requires_exception":true}'),
('FIN-CLOSE-001','Period close certification','close','Record close checklist completion and independent review evidence.','monthly','high','controller','{"evidence_required":true}'),
('FIN-VENDOR-001','Vendor master change review','vendor','Review vendor identity and sensitive master-data changes.','per_transaction','high','finance_admin','{"independent_review":true}'),
('FIN-TREASURY-001','Bank reconciliation review','treasury','Review statement reconciliation completeness and unresolved differences.','monthly','high','treasury_manager','{"unresolved_items_require_exception":true}'),
('FIN-REPORT-001','Financial report approval','reporting','Record independent review of management and statutory financial reports.','monthly','high','cfo','{"evidence_required":true}')
on conflict(control_code) do nothing;
create index if not exists mme_financial_exceptions_queue_idx on public.mme_financial_exceptions(exception_status,severity,detected_at desc);
create index if not exists mme_financial_control_execution_idx on public.mme_financial_control_executions(control_id,period_end desc);
create index if not exists mme_financial_audit_evidence_source_idx on public.mme_financial_audit_evidence(domain,source_table,source_record_id);
create or replace function public.mme_financial_exception_transition(p_exception uuid,p_status text,p_actor uuid,p_note text) returns uuid language plpgsql security definer set search_path=public as $$declare e public.mme_financial_exceptions%rowtype;begin if p_status not in('investigating','resolved','accepted_risk','false_positive','open') then raise exception 'invalid_exception_status';end if;select * into e from public.mme_financial_exceptions where exception_id=p_exception for update;if not found then raise exception 'exception_not_found';end if;if e.created_by_auth_user_id=p_actor and p_status in('resolved','accepted_risk','false_positive') then raise exception 'exception_self_review_prohibited';end if;if e.exception_status in('resolved','false_positive') and p_status<>'open' then raise exception 'exception_terminal';end if;insert into public.mme_financial_exception_events(exception_id,event_type,from_status,to_status,note,actor_auth_user_id) values(p_exception,case when p_status in('resolved','false_positive') then 'resolved' when p_status='accepted_risk' then 'risk_accepted' else 'status_changed' end,e.exception_status,p_status,left(coalesce(p_note,''),1500),p_actor);update public.mme_financial_exceptions set exception_status=p_status,resolved_by_auth_user_id=case when p_status in('resolved','accepted_risk','false_positive') then p_actor end,resolved_at=case when p_status in('resolved','accepted_risk','false_positive') then now() end,resolution_note=case when p_status in('resolved','accepted_risk','false_positive') then left(coalesce(p_note,''),1500) else resolution_note end where exception_id=p_exception;return p_exception;end$$;
create or replace function public.mme_financial_record_control_execution(p_control uuid,p_start date,p_end date,p_status text,p_evidence text,p_summary text,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$declare c public.mme_financial_control_definitions%rowtype;r uuid;begin if p_end<p_start or p_status not in('passed','failed','not_applicable','pending_review') then raise exception 'invalid_control_execution';end if;select * into c from public.mme_financial_control_definitions where control_id=p_control and active for share;if not found then raise exception 'active_control_not_found';end if;insert into public.mme_financial_control_executions(control_id,period_start,period_end,execution_status,evidence_reference,evidence_summary,executed_by_auth_user_id) values(p_control,p_start,p_end,p_status,left(p_evidence,500),left(p_summary,1500),p_actor) returning execution_id into r;return r;end$$;
do $$declare t text;begin foreach t in array array['mme_financial_control_definitions','mme_financial_control_executions','mme_financial_exceptions','mme_financial_exception_events','mme_financial_approval_authority','mme_financial_audit_evidence','mme_financial_access_reviews'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
revoke all on function public.mme_financial_exception_transition(uuid,text,uuid,text),public.mme_financial_record_control_execution(uuid,date,date,text,text,text,uuid) from public,anon,authenticated;
grant execute on function public.mme_financial_exception_transition(uuid,text,uuid,text),public.mme_financial_record_control_execution(uuid,date,date,text,text,text,uuid) to service_role;
commit;